var a=[{title:`Anatomie de bază`,text:`Coloana are regiuni cervicală, toracică, lombară, sacrală și coccigiană. Curburile ei naturale diferă de la o persoană la alta și se schimbă odată cu poziția. La multe ridicări cu sarcină, să-ți menții coloana controlată și aproape de propriul tău interval neutru confortabil este o strategie bună de început, mai ales cât timp înveți.`},{title:`Ce include „zona centrală”`,text:`Abdominalii, oblicii, mușchii profunzi ai trunchiului, extensorii spatelui, diafragma și mușchii planșeului pelvin lucrează împreună pentru a gestiona presiunea și mișcarea. Ei îndoaie trunchiul și, în același timp, se opun extensiei, rotației sau flexiei laterale nedorite în timp ce forța trece între brațe și picioare.`},{title:`Încordarea trunchiului și tragerea abdomenului înăuntru`,text:`Încordarea trunchiului înseamnă de obicei crearea de tensiune pe tot conturul lui, ca și cum te-ai pregăti pentru o împingere ușoară în stomac, păstrând respirația sub control. Tragerea abdomenului înăuntru se concentrează pe retragerea peretelui abdominal. Ambele pot avea utilitate, dar sunt instrucțiuni diferite. La ridicările grele, încordarea coordonată ajută de obicei mai mult decât simpla tragere a stomacului înăuntru.`},{title:`Presiunea intraabdominală`,text:`Diafragma și peretele abdominal pot crea o presiune internă care ajută la rigidizarea trunchiului. Strategia exactă de respirație depinde de sarcină și de experiența ta. Blocarea îndelungată și intensă a respirației poate să nu se potrivească persoanelor cu anumite afecțiuni cardiovasculare, deci dacă este cazul tău, cere sfatul medicului.`},{title:`Exemplu`,text:`Pentru o genuflexiune goblet moderată, stai drept, inspiră confortabil, încordează trunchiul, coboară cu control și expiră la urcarea grea dacă ai nevoie. La un cărat cu o singură mână, ține trunchiul vertical și nu lăsa greutatea să te tragă într-o parte.`},{title:`Antrenarea zonei centrale`,text:`Lucrul pentru zona centrală include plank-uri, dead bug, cărat și principalele tipare de mișcare, nu doar abdomene. Nicio poziție a coloanei nu este sigură pentru toată lumea, iar încordarea trunchiului nu compensează alegerea unei sarcini nepotrivite.`}];var r=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Ghid CDC privind activitatea fizică`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};